"""Requested gameplay additions only. No changes to profiled performance paths."""
from pathlib import Path
p=Path('mansion_war.html');s=p.read_text()
def hook(marker,old,new):
 global s
 if marker not in s:
  if old not in s:raise RuntimeError('Missing platform hook: '+old[:110])
  s=s.replace(old,new,1)
hook("f:'kb',name:",'const FAC_BY = {};',"FACTION_DEFS.push({f:'kb',name:'カービィ',icon:'🌟',col:'#f39bc5',group:'Kirby',panel:'panelPi_kb'},{f:'mt',name:'メタナイト',icon:'⚔️',col:'#9ba5db',group:'Kirby',panel:'panelPi_mt'},{f:'dd',name:'デデデ大王',icon:'🔨',col:'#e5b057',group:'Kirby',panel:'panelPi_dd'},{f:'bw',name:'クッパ',icon:'🐢',col:'#91bd66',group:'Super Mario',panel:'panelPi_bw'});\nconst FAC_BY = {};")
hook('  spawnPlatformHeroes();','  spawnSans();','  spawnSans();\n  spawnPlatformHeroes();')
hook('  G.platformHeroes=null;','function startGame(cfg) {','function startGame(cfg) {\n  G.platformHeroes=null;')
hook('  piInit(u);','  ssInit(u);','  ssInit(u);\n  piInit(u);\n  if(PI_CAST_OWNER){u.fac=u.team=PI_CAST_OWNER.fac;u.piAllyOf=PI_CAST_OWNER.id;u.sp={...u.sp,ai:\'platformAlly\'};}')
hook(' piTick(dt);','function updateExpansion(dt){','function updateExpansion(dt){\n piTick(dt);')
hook("case 'platformHero':", "      case 'sans':", "      case 'platformHero': thinkPlatformHero(u);break;\n      case 'platformAlly': thinkMonster(u);break;\n      case 'sans':")
hook('if(u.piCopy&&d.piCopied', 'function fireAttack(u, d, a) {', 'function fireAttack(u, d, a) {\n  if(u.piCopy&&d.piCopied&&!u.piAvatar)return piCast(u,d,a,fireAttack);\n  if(d.piPower){piFire(u,d,a);return;}')
hook('return canUse(u.piCopy.actor,d,tgt)', 'function canUse(u, d, tgt) {', 'function canUse(u, d, tgt) {\n  if(u.piMouth)return false;\n  if(u.piCopy&&d.piCopied&&!u.piAvatar)return canUse(u.piCopy.actor,d,tgt);')
hook('return piCast(u,u.atk.def', 'function updateAttack(u, dt) {', 'function updateAttack(u, dt) {\n  if(u.piCopy&&u.atk?.def.piCopied&&!u.piAvatar)return piCast(u,u.atk.def,null,actor=>updateAttack(actor,dt));')
hook('u.atk.piCopyActor=u.piCopy.actor;', '  u.cds[d.n] = G.time + d.cd;', '  if(d.piCopied&&u.piCopy&&!u.piAvatar)u.atk.piCopyActor=u.piCopy.actor;\n  u.cds[d.n] = G.time + d.cd;')
hook('if(u.piAvatar)return;', 'function startTransform(u, newKey, opts = {}) {', 'function startTransform(u, newKey, opts = {}) {\n  if(u.piAvatar)return;')
hook('if(u?.piAvatar)u=u.piOwner;', 'function killUnit(att, u, o = {}) {', 'function killUnit(att, u, o = {}) {\n  if(u?.piAvatar)u=u.piOwner;')
hook('  piOnDeath(att,u);','  slOnDeath(att,u,o);','  slOnDeath(att,u,o);\n  piOnDeath(att,u);')
hook('if(u.piReservedFor||u.piConsumed)return;', 'function makeCorpse(u, opts = {}) {', 'function makeCorpse(u, opts = {}) {\n  if(u.piReservedFor||u.piConsumed)return;')
hook('if(u.piInhaledBy)return;', 'function updateUnit(u, dt) {', 'function updateUnit(u, dt) {\n  if(u.piInhaledBy)return;')
