hook('if(u.piInhaledBy||o.piInhaledBy)return false;', '  if (u === o) return false;', '  if (u === o) return false;\n  if(u.piInhaledBy||o.piInhaledBy)return false;')
hook("if(['kb','mt','dd','bw'].includes(u.fac)", "  if(u.fac==='sk'||o.fac==='sk')", "  if(['kb','mt','dd','bw'].includes(u.fac)||['kb','mt','dd','bw'].includes(o.fac))return u.fac!==o.fac;\n  if(u.fac==='sk'||o.fac==='sk')")
hook('if(u.piInhaledBy)return; // hidden in mouth', 'function drawUnit(u) {', 'function drawUnit(u) {\n  if(u.piInhaledBy)return; // hidden in mouth')
