hook('  piInspector(el,u);','  ssInspector(el,u);','  ssInspector(el,u);\n  piInspector(el,u);')
hook("...PI_FACTIONS.map(([f,n,ic,c,k])",'  const extraFac = [',"  const extraFac = [\n    ...PI_FACTIONS.map(([f,n,ic,c,k])=>[f,'panelPi_'+f,ic+' '+n,c,[k]]),")
hook("if(u.key==='piKirby')return piPlayerAttack", " if(u.sp.slEra==='mini')return slMightyPlayerAttack(u,index);", " if(u.key==='piKirby')return piPlayerAttack(u,index);\n if(u.sp.slEra==='mini')return slMightyPlayerAttack(u,index);")
hook('!u.piInhaledBy&&!u.dead', 'return !!u&&!u.dead&&!u.gone&&!u.tf', 'return !!u&&!u.piInhaledBy&&!u.dead&&!u.gone&&!u.tf')
hook('u.gone || u.piInhaledBy || u.x < vx0', 'u.gone || u.x < vx0', 'u.gone || u.piInhaledBy || u.x < vx0')
hook('!u.gone && !u.piInhaledBy && (u.z || 0)', '!u.gone && (u.z || 0)', '!u.gone && !u.piInhaledBy && (u.z || 0)')
# A copied summon must not be blocked just because its source faction was disabled.
s=s.replace('if (G.facOff && G.facOff[sp.fac]) return null;', 'if (G.facOff && G.facOff[sp.fac] && !PI_CAST_OWNER) return null;')
